mapper.insert:
INSERT INTO table_export (
    id, title, row_count, session_id
) VALUES (
    #{id}, #{title}, #{rowCount}, #{sessionId}
)

mapper.select:
SELECT te.* FROM table_export te


        te.session_id = #{sessionId}


        AND EXISTS (
            SELECT 1 FROM user_session us
            WHERE us.session_id = te.session_id AND us.user_id = #{userId}
        )


ORDER BY te.create_time DESC
